package com.vibecode.task.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="tasks") public class WorkflowTask { @Id private UUID id; @Column(name="project_id",nullable=false) private UUID projectId; @Column(name="phase_id",nullable=false) private UUID phaseId; @Column(nullable=false) private int position; @Column(nullable=false) private String title; @Column(nullable=false,columnDefinition="TEXT") private String objective; @Enumerated(EnumType.STRING) @Column(nullable=false) private WorkflowTaskStatus status; @Enumerated(EnumType.STRING) @Column(name="risk_level",nullable=false) private RiskLevel riskLevel; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; @Column(name="started_at") private Instant startedAt; @Column(name="completed_at") private Instant completedAt; protected WorkflowTask(){} public WorkflowTask(UUID projectId,UUID phaseId,int position,String title,String objective,RiskLevel risk){id=UUID.randomUUID();this.projectId=projectId;this.phaseId=phaseId;this.position=position;this.title=title;this.objective=objective;riskLevel=risk;status=WorkflowTaskStatus.PLANNED;createdAt=updatedAt=Instant.now();} public UUID id(){return id;} public UUID projectId(){return projectId;} public UUID phaseId(){return phaseId;} public int position(){return position;} public String title(){return title;} public String objective(){return objective;} public WorkflowTaskStatus status(){return status;} public RiskLevel riskLevel(){return riskLevel;} public void status(WorkflowTaskStatus s){status=s;updatedAt=Instant.now();if(s==WorkflowTaskStatus.IN_PROGRESS&&startedAt==null)startedAt=updatedAt;if(s==WorkflowTaskStatus.COMPLETED)completedAt=updatedAt;}}
